const api=async<T,>(url:string,init?:RequestInit):Promise<T>=>{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),10000);let r:Response;try{r=await fetch(url,{headers:{'Content-Type':'application/json'},...init,signal:init?.signal??controller.signal})}catch(error){if(controller.signal.aborted)throw Error(`Request timed out: ${url}`);throw error}finally{clearTimeout(timeout)};const contentType=r.headers.get('content-type')??'';const body=contentType.includes('application/json')?await r.json():await r.text();if(!r.ok)throw Error(typeof body==='object'&&body&&'error'in body?String((body as{error:unknown}).error):`${r.status} ${r.statusText}: ${String(body).slice(0,160)}`);if(!contentType.includes('application/json'))throw Error(`Expected JSON from ${url} but received ${contentType||'unknown content type'}`);return body as T};
